#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "clip_hierarchy.h"
#include "session_camera_view_projection_candidate.h"
#include <iostream>
int main(int argc,char**argv){try{static_assert(sizeof(void*)==8,"x64 required");if(argc!=3&&argc!=4)throw std::runtime_error("session and fresh matrix output required");if(std::filesystem::exists(argv[2]))throw std::runtime_error("refuse matrix overwrite");bool engineAxes=argc==4&&std::string(argv[3])=="engine";if(argc==4&&!engineAxes)throw std::runtime_error("camera mode");auto graph=loadGraph(argv[1]);size_t count=0;RenderCameraCandidate first{};for(uint32_t n=0;n<graph.elements.size();++n)if(graph.strings.at(graph.elements[n].type)=="DmeCamera"){auto settings=readSessionCameraSettingsCandidate(graph,n);auto local=graphLocalTransformMatrix(graph,settings.transform);if(engineAxes)local=engineCameraBasisCandidate(local);auto camera=sessionCameraViewProjectionCandidate(graph,n,512,512,engineAxes);std::array<float,3>nearPoint;for(size_t r=0;r<3;++r)nearPoint[r]=local[r][3]-local[r][2]*settings.nearPlane;auto clip=camera.clip(nearPoint);double bound=std::abs(camera.rows[11]);for(size_t r=0;r<3;++r)bound+=std::abs(double(camera.rows[8+r])*nearPoint[r]);bound*=16*std::numeric_limits<float>::epsilon();if(clip[3]<=0||std::abs(clip[2])>std::max(1e-4,bound))throw std::runtime_error("session camera near-plane composition");if(count==0)first=camera;++count;}if(!count)throw std::runtime_error("no camera");std::ofstream out(argv[2],std::ios::binary);out.write(reinterpret_cast<const char*>(&first),64);out.close();if(!out)throw std::runtime_error("matrix write");std::cout<<"session camera view/projection candidates="<<count<<" near_plane_checks="<<count<<" exported_bytes=64 viewport=512x512 engine_axes="<<engineAxes<<" full_native_parity=unverified\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}

